    print("1. Show developer information")
    print("2. Show supported languages")
    print("3. Check username")
    print("4. Show project health")
    print("5. Exit")


def process_choice(choice):
    if choice == "1":
        print(developer_summary("Rahul", "Python", 1))
    elif choice == "2":
        show_languages(["Python", "JavaScript", "Java", "Go"])
    elif choice == "3":
        username = input()
        if is_valid_username(username):
            print("Valid username")
        else:
            print("Invalid username")
    elif choice == "4":
        coverage = calculate_coverage(20, 8)
        if coverage >= 30:
            print("Good test coverage")
        else:
            print("Test coverage needs improvement")
    elif choice == "5":
        return False
    else:
        print("Invalid choice")

    return True


def run_menu():
    while True:
        show_menu()
        choice = input()
        if not process_choice(choice):
            break
